# Online Python compiler (interpreter)# Write and run Python online using this editor.import timedef generar_pascal_y_evaluar(n, x):    # 1. Memoria dinámica (lista que crece dinámicamente)    fila = [0] * (n + 1)    fila[0] = 1        # 2. Generar coeficientes (Triángulo de Pascal)    for i in range(1, n + 1):        for j in range(i, 0, -1):            fila[j] = fila[j] + fila[j-1]                # 3. Mostrar Polinomio    terminos = []    for i, coef in enumerate(fila):        potencia = n - i        if potencia == 0:            terminos.append(f"{coef}")        elif potencia == 1:            terminos.append(f"{coef}x")        else:            terminos.append(f"{coef}x^{potencia}")        print(f"Polinomio (x+1)^{n}:")    print(" + ".join(terminos))        # 4. Evaluación paso a paso    print(f"\nEvaluación paso a paso para x = {x}:")    resultado = 0    for i, coef in enumerate(fila):        potencia = n - i        valor_termino = coef * (x ** potencia)        resultado += valor_termino        print(f"  {coef} * {x}^{potencia} = {valor_termino}  -> Acumulado: {resultado}")           print(f"\nResultado final f({x}) = {resultado}")# --- PRUEBA CON EL EJEMPLO DEL PDF ---print("--- PRUEBA CON n=5, x=2 ---")generar_pascal_y_evaluar(5, 2)# --- MEDICIÓN DE TIEMPO PARA N=100 ---print("\n--- TIEMPO DE GENERACIÓN PARA N=100 ---")inicio = time.perf_counter()# Hacemos la generación sin imprimir para medir solo el cálculon = 100fila_100 = [0] * (n + 1)fila_100[0] = 1for i in range(1, n + 1):    for j in range(i, 0, -1):        fila_100[j] = fila_100[j] + fila_100[j-1]fin = time.perf_counter()print(f"Tiempo en Python para n=100: {(fin - inicio) * 1000:.6f} milisegundos")